package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import static com.example.yuejie.PaperUi.*;
public class DetailActivity extends Activity {
 LocalLibrary library;NovelApi api;Book book;boolean loading=true;String error="";int generation=0;
 int d(float n){return dp(this,n);}
 public void onCreate(Bundle b){super.onCreate(b);bars(this,false);library=new LocalLibrary(this);api=new NovelApi(this,library);try{book=new Book(new JSONObject(getIntent().getStringExtra("book")));}catch(Exception e){finish();return;}render();load();}
 protected void onResume(){super.onResume();if(book!=null)render();}
 void load(){loading=true;error="";int token=++generation;render();NovelApi.async(()->api.detail(book.id),(value,err)->{if(isFinishing()||token!=generation)return;loading=false;if(err==null){book=value;}else error=err;render();});}
 void read(){startActivity(new Intent(this,ReaderActivity.class).putExtra("book_id",book.id).putExtra("book_name",book.title));}
 void catalog(){NovelApi.async(()->api.directory(book.id,false),(data,err)->{if(isFinishing())return;if(err!=null){new AlertDialog.Builder(this).setMessage(err).setPositiveButton("重试",(x,n)->catalog()).setNegativeButton("返回",null).show();return;}ChapterSheet.show(this,book.title,data,-1,(index)->{startActivity(new Intent(this,ReaderActivity.class).putExtra("book_id",book.id).putExtra("book_name",book.title).putExtra("chapter_index",index));},false,null);});}
 void render(){LinearLayout root=col(this);root.setBackgroundColor(PAPER);root.setFitsSystemWindows(true);setContentView(root);LinearLayout bar=row(this);bar.setPadding(d(10),d(2),d(16),d(2));bar.addView(icon(this,"返回",MUTED,44,()->finish()));bar.addView(text(this,"书籍详情",12,MUTED));root.addView(bar);ScrollView scroll=new ScrollView(this);LinearLayout body=col(this);body.setPadding(d(24),d(20),d(24),d(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout row=row(this);row.setGravity(Gravity.TOP);row.addView(cover(this,book,100));LinearLayout copy=col(this);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=d(20);row.addView(copy,cp);copy.addView(heading(this,book.title,23));gap(copy,12);copy.addView(text(this,book.author,13,MUTED));gap(copy,10);copy.addView(text(this,book.category+(book.words.isEmpty()?"":" · "+wordCount(book.words)),11,GREEN));gap(copy,10);String state=book.raw.optString("creation_status");if(!state.isEmpty())copy.addView(text(this,("0".equals(state)||"2".equals(state))?"已完结":"连载中",11,MUTED));body.addView(row);gap(body,27);body.addView(heading(this,"作品简介",19));gap(body,13);TextView description=text(this,book.summary.isEmpty()?"暂无简介":book.summary,14,INK);description.setLineSpacing(d(5),1.4f);body.addView(description);gap(body,28);rule(body);gap(body,15);body.addView(button(this,"查看完整目录"+(book.raw.optInt("chapter_count")>0?" · "+book.raw.optInt("chapter_count")+" 章":""),()->catalog()));if(loading){gap(body,16);body.addView(text(this,"正在加载书籍详情…",12,MUTED));}else if(!error.isEmpty()){gap(body,16);body.addView(text(this,error,12,MUTED));body.addView(button(this,"重新加载详情",()->load()));}
 LinearLayout actions=row(this);actions.setPadding(d(24),d(12),d(24),d(15));TextView add=button(this,library.contains(book.id)?"已在书架 · 移出":"加入书架",()->{if(library.contains(book.id))library.remove(book.id);else library.add(book);render();});actions.addView(add,new LinearLayout.LayoutParams(0,d(48),1));TextView read=button(this,library.progress(book.id)==null?"开始阅读":"继续阅读",()->read());read.setTextColor(PAPER);read.setBackground(bg(this,GREEN,10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,d(48),1);lp.leftMargin=d(12);actions.addView(read,lp);rule(root);root.addView(actions);}
 static String wordCount(String v){try{return String.format(java.util.Locale.CHINA,"%.1f 万字",Double.parseDouble(v)/10000);}catch(Exception e){return v;}}
 protected void onDestroy(){generation++;super.onDestroy();}
}
